// Lấy mã đơn từ sự kiện Router và dựng lời gọi chi tiết đơn
const e = $input.first().json;
const orderId = String((e.data || {}).order_id || e.order_id || '');
if (!orderId) throw new Error('Sự kiện không có data.order_id');
return [{ json: { method: 'GET', path: '/order/202309/orders', query: { ids: orderId }, tiktok_order_id: orderId } }];

const ODOO = { url: ($env.ODOO_URL || 'http://odoo:8069') + '/jsonrpc', db: $env.ODOO_DB || 'hdx',
  login: $env.ODOO_N8N_LOGIN || 'n8n', pw: $env.ODOO_N8N_PASSWORD || '' };
if (!ODOO.pw) throw new Error('Thiếu ODOO_N8N_PASSWORD trong .env');
// Gọi JSON-RPC của Odoo, ném lỗi kèm thông báo của Odoo
const rpc = async (service, method, args) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: ODOO.url, json: true, timeout: 30000,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } } });
  if (r.error) throw new Error(`Odoo: ${(r.error.data && r.error.data.message) || r.error.message}`);
  return r.result;
};
const uid = await rpc('common', 'login', [ODOO.db, ODOO.login, ODOO.pw]);
if (!uid) throw new Error('Odoo: sai ODOO_N8N_LOGIN hoặc ODOO_N8N_PASSWORD');
// Gọi một method của model Odoo
const call = (model, method, args, kw = {}) => rpc('object', 'execute_kw', [ODOO.db, uid, ODOO.pw, model, method, args, kw]);

const orderId = $('Yêu cầu chi tiết đơn').first().json.tiktok_order_id;
const r = $input.first().json;
if (!r.ok) throw new Error(`Lấy chi tiết đơn ${orderId} lỗi: ${r.code} ${r.message}`);
const order = ((r.data || {}).orders || [])[0];
if (!order) throw new Error(`TikTok không trả về đơn ${orderId}`);
const qty = {};
for (const li of order.line_items || []) {
  if (!li.seller_sku) throw new Error(`Đơn ${orderId} có dòng hàng thiếu seller_sku`);
  qty[li.seller_sku] = (qty[li.seller_sku] || 0) + (Number(li.quantity) || 1);
}
const skus = Object.keys(qty);
if (!skus.length) throw new Error(`Đơn ${orderId} không có dòng hàng`);
const found = await call('sale.order', 'search_read', [[['client_order_ref', '=', orderId]]], { fields: ['name', 'state'], limit: 1 });
if (found.length) {
  if (found[0].state === 'draft') await call('sale.order', 'action_confirm', [[found[0].id]]);
  return [{ json: { tiktok_order_id: orderId, odoo_sale_order: found[0].name, created: found[0].state === 'draft', seller_skus: skus } }];
}
const prods = await call('product.product', 'search_read', [[['default_code', 'in', skus]]], { fields: ['default_code'] });
const byCode = Object.fromEntries(prods.map((p) => [p.default_code, p.id]));
const missing = skus.filter((s) => !byCode[s]);
if (missing.length) throw new Error(`Odoo chưa có sản phẩm ${missing.join(', ')}: chạy scripts/dung-odoo.py`);
const buyer = String(order.user_id || 'khach');
const ref = `tiktok:${buyer}`;
let partner = (await call('res.partner', 'search', [[['ref', '=', ref]]], { limit: 1 }))[0];
if (!partner) {
  const name = (order.recipient_address || {}).name || `Khách ${buyer}`;
  partner = await call('res.partner', 'create', [{ name, ref, comment: 'Tạo tự động từ đơn TikTok hoặc web giả lập' }]);
}
const soId = await call('sale.order', 'create', [{ partner_id: partner, client_order_ref: orderId, origin: `TikTok ${orderId}`,
  order_line: skus.map((s) => [0, 0, { product_id: byCode[s], product_uom_qty: qty[s] }]) }]);
await call('sale.order', 'action_confirm', [[soId]]);
const so = (await call('sale.order', 'read', [[soId]], { fields: ['name', 'amount_total'] }))[0];
return [{ json: { tiktok_order_id: orderId, odoo_sale_order: so.name, created: true, amount_total: so.amount_total, seller_skus: skus } }];

